import { IconButton } from '@refy-design/web';
import { ThemeProvider } from '@refy-design/web';
import type { ComponentProps } from 'react';
const Search = (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth={1.8}
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <circle cx="11" cy="11" r="7" />
    <path d="m21 21-4.3-4.3" />
  </svg>
);
export function Example() {
  const args: Pick<
    ComponentProps<typeof IconButton>,
    'aria-label' | 'icon' | 'variant' | 'size'
  > = { 'aria-label': 'Search', icon: Search, variant: 'ghost', size: 'md' };
  return (
    <ThemeProvider
      theme={{
        name: 'Icon size',
        tokens: { '--icon-button-lg': '36px', '--icon-button-icon-lg': '20px' },
      }}
    >
      <IconButton {...args} size="lg" data-testid="iconbutton-lg" />
    </ThemeProvider>
  );
}
